import React, { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { FiArrowLeft, FiTrash2, FiPlus } from "react-icons/fi";
import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import DataTable from "../../components/DataTable";
import ConfirmDialog from "../../components/ConfirmDialog";
import Loading from "../../components/Loading";
import StatusBadge from "../../components/StatusBadge";
import { studentApi } from "../../api/studentApi";
import { registrationApi } from "../../api/registrationApi";
import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";
import { fullName, formatDateTime } from "../../utils/formatters";

export default function StudentCourses() {
  const { id } = useParams();
  const navigate = useNavigate();
  const toast = useToast();

  const [student, setStudent] = useState(null);
  const [courses, setCourses] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [dropTarget, setDropTarget] = useState(null);
  const [isDropping, setIsDropping] = useState(false);

  function load() {
    setIsLoading(true);
    Promise.allSettled([studentApi.getOne(id), registrationApi.getByStudent(id)]).then(
      ([studentRes, coursesRes]) => {
        if (studentRes.status === "fulfilled") {
          setStudent(studentRes.value.data?.data || studentRes.value.data);
        } else {
          toast.error(extractErrorMessage(studentRes.reason, "Student not found."));
          navigate("/registrations");
          return;
        }
        if (coursesRes.status === "fulfilled") {
          const list = coursesRes.value.data?.data || coursesRes.value.data || [];
          setCourses(Array.isArray(list) ? list : []);
        } else {
          setError(extractErrorMessage(coursesRes.reason, "Unable to load registered courses."));
        }
        setIsLoading(false);
      }
    );
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  async function confirmDrop() {
    setIsDropping(true);
    try {
      await registrationApi.remove(dropTarget.id);
      toast.success("Course dropped successfully");
      setDropTarget(null);
      load();
    } catch (err) {
      toast.error(extractErrorMessage(err, "Unable to drop this course."));
    } finally {
      setIsDropping(false);
    }
  }

  const columns = [
    { key: "student", label: "Student", render: () => fullName(student) },
    { key: "course_code", label: "Course Code", render: (r) => <span className="font-mono text-xs bg-navy-50 text-navy-700 px-2 py-1 rounded">{r.course_code || r.course?.code}</span> },
    { key: "course_name", label: "Course Name", render: (r) => r.course_name || r.course?.name },
    { key: "credit_hour", label: "Credit Hour", render: (r) => r.credit_hour ?? r.course?.credit_hour, hideOnMobile: true },
    { key: "semester", label: "Semester" },
    { key: "academic_year", label: "Academic Year", hideOnMobile: true },
    { key: "registered_at", label: "Registered At", render: (r) => formatDateTime(r.registered_at), hideOnMobile: true },
    { key: "status", label: "Status", render: (r) => <StatusBadge status={r.status || "registered"} /> },
    {
      key: "actions",
      label: "Actions",
      render: (r) => (
        <button
          onClick={() => setDropTarget(r)}
          className="flex items-center gap-1.5 text-xs font-medium text-red-600 hover:bg-red-50 px-2.5 py-1.5 rounded-md"
        >
          <FiTrash2 size={13} /> Drop
        </button>
      )
    }
  ];

  if (isLoading) {
    return (
      <DashboardLayout>
        <Loading label="Loading registered courses..." />
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <Link to="/registrations" className="inline-flex items-center gap-1.5 text-sm text-navy-600 hover:text-navy-800 mb-4">
        <FiArrowLeft size={14} /> Back to Student Search
      </Link>

      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <div>
          <h1 className="font-display text-xl text-navy-800">{student ? fullName(student) : "Student"}</h1>
          <p className="text-sm text-muted font-mono">{student?.registration_number}</p>
        </div>
        <Link
          to="/registrations/create"
          className="flex items-center gap-2 bg-navy-700 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-navy-800 transition"
        >
          <FiPlus size={15} /> Register New Course
        </Link>
      </div>

      <Card>
        <DataTable
          columns={columns}
          rows={courses}
          isLoading={false}
          error={error}
          emptyTitle="No courses have been registered yet."
          emptyDescription="Register this student into a course to see it appear here."
          emptyAction={{ label: "Register Course", onClick: () => navigate("/registrations/create") }}
        />
      </Card>

      <ConfirmDialog
        isOpen={Boolean(dropTarget)}
        onClose={() => setDropTarget(null)}
        onConfirm={confirmDrop}
        isLoading={isDropping}
        title="Drop this course?"
        confirmLabel="Drop Course"
        itemLabel={dropTarget ? `${dropTarget.course_code || dropTarget.course?.code} — ${dropTarget.course_name || dropTarget.course?.name}` : ""}
        description="The student will be unregistered from this course. This action cannot be undone."
      />
    </DashboardLayout>
  );
}
